result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "cribbage.py", "content": """"Cribbage hand scoring: 4-card hand + starter."""

from itertools import combinations
from collections import Counter

RANK_ORDER = "A23456789TJQK"


def _parse(card):
    """'5H' -> (rank_value_for_15, rank_index_for_runs, suit).

    Rank value: A=1, face/T=10. Rank index: position in A..K (runs use A-low).
    """
    r, suit = card[:-1], card[-1]
    r = r.upper()
    if r == "10":
        r = "T"
    idx = RANK_ORDER.index(r)
    return min(idx + 1, 10), idx, suit


def score(hand, starter):
    """Score a 4-card hand plus the starter card."""
    cards = [_parse(c) for c in list(hand) + [starter]]
    vals = [v for v, _, _ in cards]
    idxs = [i for _, i, _ in cards]

    total = 0

    # Fifteens: every subset of the 5 cards summing to 15 -> 2 points.
    for n in range(2, len(vals) + 1):
        for combo in combinations(vals, n):
            if sum(combo) == 15:
                total += 2

    # Pairs: a rank appearing c times contributes C(c,2) pairs -> 2 points each.
    counts = Counter(idxs)
    for c in counts.values():
        total += 2 * c * (c - 1) // 2

    # Runs: on distinct ranks, each maximal run of length L>=3 scores
    # L times the product of multiplicities of its ranks.
    distinct = sorted(counts)
    run = [distinct[0]]
    for r in distinct[1:]:
        if r == run[-1] + 1:
            run.append(r)
        else:
            if len(run) >= 3:
                total += len(run) * _mult(run, counts)
            run = [r]
    if len(run) >= 3:
        total += len(run) * _mult(run, counts)

    # Flush: 4 cards of the same suit in the HAND -> 4;
    # all five (starter too) match -> 5.
    hand_suits = [_parse(c)[2] for c in hand]
    if len(set(hand_suits)) == 1:
        total += 5 if hand_suits[0] == _parse(starter)[2] else 4

    # His nobs: a Jack in the hand whose suit matches the starter's suit.
    for c in hand:
        v, i, s = _parse(c)
        if RANK_ORDER[i] == "J" and s == _parse(starter)[2]:
            total += 1

    return total


def _mult(run, counts):
    m = 1
    for r in run:
        m *= counts[r]
    return m
